// Consistent Hash Ring using TreeMap and virtual nodes (Java)
public final class ConsistentHashRing {
    private final NavigableMap<Long, String> ring = new TreeMap<>();
    private final int vnodesPerHost;

    public ConsistentHashRing(int vnodesPerHost) {
        this.vnodesPerHost = vnodesPerHost;
    }

    public synchronized void addHost(String hostId) {
        for (int i = 0; i < vnodesPerHost; i++) {
            ring.put(murmur64(hostId + "#" + i), hostId);
        }
    }

    public synchronized String routeKey(String key) {
        if (ring.isEmpty()) throw new IllegalStateException("Empty ring");
        long hash = murmur64(key);
        Map.Entry<Long, String> entry = ring.ceilingEntry(hash);
        return (entry != null) ? entry.getValue() : ring.firstEntry().getValue();
    }
}
